CREATE TABLE mcp_connections(id uuid PRIMARY KEY,owner_id uuid NOT NULL REFERENCES users(id),name text NOT NULL,endpoint jsonb NOT NULL,secret_id uuid,header_names jsonb NOT NULL DEFAULT '[]',revision bigint NOT NULL DEFAULT 1,enabled boolean NOT NULL DEFAULT true,status text NOT NULL DEFAULT 'REVIEW_REQUIRED',server_info jsonb,last_discovery timestamptz,last_activity timestamptz,last_error text,UNIQUE(owner_id,id));
CREATE TABLE mcp_tools(id uuid PRIMARY KEY,owner_id uuid NOT NULL,connection_id uuid NOT NULL,original_name text NOT NULL,registry_name text NOT NULL,descriptor jsonb NOT NULL,schema_digest text NOT NULL,revision bigint NOT NULL DEFAULT 1,enabled boolean NOT NULL DEFAULT false,effect_assessment text NOT NULL DEFAULT 'UNKNOWN' CHECK(effect_assessment IN('UNKNOWN','READ_ONLY','MODIFIES_DATA','FORBIDDEN')),review_reason text NOT NULL DEFAULT 'New tool: default denied',UNIQUE(owner_id,id),UNIQUE(owner_id,connection_id,original_name),UNIQUE(owner_id,registry_name),FOREIGN KEY(owner_id,connection_id) REFERENCES mcp_connections(owner_id,id));
CREATE TABLE mcp_grants(owner_id uuid NOT NULL,tool_id uuid NOT NULL,schema_digest text NOT NULL,revision bigint NOT NULL,assessment text NOT NULL,review_evidence text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(owner_id,tool_id),FOREIGN KEY(owner_id,tool_id) REFERENCES mcp_tools(owner_id,id));
CREATE TABLE mcp_call_evidence(id uuid PRIMARY KEY,owner_id uuid NOT NULL,connection_id uuid NOT NULL,authorization_id uuid NOT NULL UNIQUE,tool_name text NOT NULL,schema_digest text NOT NULL,state text NOT NULL CHECK(state IN('SUBMITTED','COMPLETED','FAILED','OUTCOME_UNKNOWN')),protocol_evidence jsonb,created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(owner_id,connection_id) REFERENCES mcp_connections(owner_id,id));
